/// <summary>
///
/// </summary>
public void init()
{
    super();
    NVEmpOvertimeHeader     header = this.args().record();
    NVEmpOvertimeLine       overTimeLine, overtimeLineEachType, overtimeLineDeduction, flightRate, groundRate;
    NVPositionOvertimeGroup positionOVertimeGroup;
    int                     hoursToDeduct, remainingFlightDay, remainingFlightNight, remainingGroundDay, remainingGroundNight;
    TransDate               overtimeDate;

    while select EmpId,PositionId from overTimeLine
        group by overTimeLine.EmpId, overTimeLine.PositionId
        where overTimeLine.OvertimeId == header.OvertimeId
    {
        remainingFlightDay = 0;
        remainingFlightNight = 0;
        remainingGroundDay = 0;
        remainingGroundNight = 0;

        NVEmpOvertimeSummary.clear();
        NVEmpOvertimeSummary.EmpId = overTimeLine.EmpId;
        NVEmpOvertimeSummary.Name = HcmWorker::findByPersonnelNumber(overTimeLine.EmpId).name();
        NVEmpOvertimeSummary.PositionId = overTimeLine.PositionId;
        positionOVertimeGroup = NVPositionOvertimeGroup::findByPosition(HcmPosition::findByPosition(NVEmpOvertimeSummary.PositionId).RecId);

        select firstonly DayRate, NightRate, FlightHoursLimit from flightRate
            where flightRate.OvertimeId == header.OvertimeId
            && flightRate.EmpId == overTimeLine.EmpId
            && flightRate.State == NVOvertimeWorkState::Flight;

        select firstonly DayRate, NightRate, FlightHoursLimit from groundRate
            where groundRate.OvertimeId ==  header.OvertimeId
            && groundRate.EmpId == overTimeLine.EmpId
            && groundRate.State == NVOvertimeWorkState::Ground;

            hoursToDeduct = flightRate.FlightHoursLimit * 60;
        NVOvertimeWorkState     lastRecordState;
        while select DayMinutes, NightMinutes, TransDate, State from overtimeLineDeduction
            order by TransDate, State asc
            where (overtimeLineDeduction.OvertimeId == header.OvertimeId
            && overtimeLineDeduction.EmpId == overTimeLine.EmpId)
        {
            if(hoursToDeduct <= 0)
                break;
            lastRecordState = overtimeLineDeduction.State;
            overtimeDate = overtimeLineDeduction.TransDate;
            if(hoursToDeduct - overtimeLineDeduction.DayMinutes >= 0)
            {
                hoursToDeduct = hoursToDeduct - overtimeLineDeduction.DayMinutes;
            }
            else
            {
                if(overtimeLineDeduction.State == NVOvertimeWorkState::Flight)
                {
                    remainingFlightDay = overtimeLineDeduction.DayMinutes - hoursToDeduct;
                }
                else
                {
                    remainingGroundDay = overtimeLineDeduction.DayMinutes - hoursToDeduct;
                }
                hoursToDeduct = 0;
            }
            if(hoursToDeduct - overtimeLineDeduction.NightMinutes >= 0)
            {
                hoursToDeduct = hoursToDeduct - overtimeLineDeduction.NightMinutes;
            }
            else
            {
                if(overtimeLineDeduction.State == NVOvertimeWorkState::Flight)
                {
                    remainingFlightNight = overtimeLineDeduction.NightMinutes - hoursToDeduct;
                }
                else
                {
                    remainingGroundNight = overtimeLineDeduction.NightMinutes - hoursToDeduct;
                }
                hoursToDeduct = 0;
                break;
            }
        }

        if(lastRecordState == NVOvertimeWorkState::Flight)
        {
            select DayMinutes, NightMinutes from overtimeLineEachType
            where overtimeLineEachType.OvertimeId == header.OvertimeId
            && overtimeLineEachType.EmpId == NVEmpOvertimeSummary.EmpId
            && overtimeLineEachType.TransDate == overtimeDate
                && overtimeLineEachType.State == NVOvertimeWorkState::Ground;

            remainingGroundDay = overtimeLineEachType.DayMinutes;
            remainingGroundNight = overtimeLineEachType.NightMinutes;
        }

        select sum(DayMinutes), sum(NightMinutes) from overtimeLineEachType
            where overtimeLineEachType.OvertimeId == header.OvertimeId
            && overtimeLineEachType.EmpId == NVEmpOvertimeSummary.EmpId
            && overtimeLineEachType.TransDate > overtimeDate
            && overtimeLineEachType.State == NVOvertimeWorkState::Flight;

        NVEmpOvertimeSummary.FlightDayHours = (overtimeLineEachType.DayMinutes + remainingFlightDay) / 60;
        NVEmpOvertimeSummary.FlightDayRate = flightRate.DayRate;
        NVEmpOvertimeSummary.FlightNightHours = (overtimeLineEachType.NightMinutes + remainingFlightNight) / 60;
        NVEmpOvertimeSummary.FlightNightRate = flightRate.NightRate;

        select sum(DayMinutes), sum(NightMinutes) from overtimeLineEachType
            where overtimeLineEachType.OvertimeId == header.OvertimeId
            && overtimeLineEachType.EmpId == NVEmpOvertimeSummary.EmpId
            && overtimeLineEachType.TransDate > overtimeDate
            && overtimeLineEachType.State == NVOvertimeWorkState::Ground;


        NVEmpOvertimeSummary.GroundDayHours = (overtimeLineEachType.DayMinutes + remainingGroundDay) / 60;
        NVEmpOvertimeSummary.GroundDayRate = groundRate.DayRate;
        NVEmpOvertimeSummary.GroundNightHours = (overtimeLineEachType.NightMinutes + remainingGroundNight) / 60;
        NVEmpOvertimeSummary.GroundNightRate = groundRate.NightRate;

        NVEmpOvertimeSummary.TotalOvertimeAmount = (NVEmpOvertimeSummary.FlightDayHours * NVEmpOvertimeSummary.FlightDayRate) +
                                                    (NVEmpOvertimeSummary.FlightNightHours * NVEmpOvertimeSummary.FlightNightRate) +
                                                    (NVEmpOvertimeSummary.GroundDayHours * NVEmpOvertimeSummary.GroundDayRate) +
                                                    (NVEmpOvertimeSummary.GroundNightHours * NVEmpOvertimeSummary.GroundNightRate);

        NVEmpOvertimeSummary.insert();

        //flightDay = overtimeLineEachType.DayMinutes;
        //flightNight = overtimeLineEachType.NightMinutes;


        //hoursToDeduct = overtimeRate.FlightHoursLimit * 60;
        //if(hoursToDeduct > flightDay)
        //{
        //    hoursToDeduct = hoursToDeduct - flightDay;
        //    flightDay = 0;
        //}
        //else
        //{
        //    flightDay = flightDay - hoursToDeduct;
        //    hoursToDeduct = 0;
        //}

        //if(hoursToDeduct && hoursToDeduct > flightNight)
        //{
        //    hoursToDeduct = hoursToDeduct - flightNight;
        //    flightNight = 0;
        //}
        //else
        //{
        //    flightNight = flightNight - hoursToDeduct;
        //    hoursToDeduct = 0;
        //}


        //groundDay = overtimeLineEachType.DayMinutes;
        //groundNight = overtimeLineEachType.NightMinutes;

        //if(hoursToDeduct > groundDay)
        //{
        //    hoursToDeduct = hoursToDeduct - groundDay;
        //    groundDay = 0;
        //}
        //else
        //{
        //    groundDay = groundDay - hoursToDeduct;
        //    hoursToDeduct = 0;
        //}

        //if(hoursToDeduct && hoursToDeduct > groundNight)
        //{
        //    hoursToDeduct = hoursToDeduct - groundNight;
        //    groundNight = 0;
        //}
        //else
        //{
        //    groundNight = groundNight - hoursToDeduct;
        //    hoursToDeduct = 0;
        //}




    }
}
